describe('Search Spelling Tolerance', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="search-input"]').as('searchInput');
  });

  it('should find results with minor spelling mistakes - single character typo', () => {
    cy.get('@searchInput').type('electronis');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="search-result-item"]').first().should('contain', 'electronics');
  });

  it('should find results with transposed characters', () => {
    cy.get('@searchInput').type('lapton');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="search-result-item"]').first().should('contain', 'laptop');
  });

  it('should find results with missing character', () => {
    cy.get('@searchInput').type('headpones');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="search-result-item"]').first().should('contain', 'headphones');
  });

  it('should find results with extra character', () => {
    cy.get('@searchInput').type('cameraa');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="search-result-item"]').first().should('contain', 'camera');
  });

  it('should handle case insensitivity with typos', () => {
    cy.get('@searchInput').type('MONITER');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="search-result-item"]').first().invoke('text').then((text) => {
      expect(text.toLowerCase()).to.include('monitor');
    });
  });

  it('should not return results for completely unrelated misspellings', () => {
    cy.get('@searchInput').type('xyzabc');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length', 0);
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');
  });

  it('should clear previous results when new search is performed', () => {
    cy.get('@searchInput').type('lapton');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);

    cy.get('@searchInput').clear();
    cy.get('@searchInput').type('moniter');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-result-item"]').first().should('contain', 'monitor');
  });

  it('should handle empty search input gracefully', () => {
    cy.get('@searchInput').type(' ');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('be.visible');
  });
});
